#[test]
fn bond_identifier_variants_equality_and_match() {
    let c = BondIdentifier::Cusip(Cusip::new("037833100"));
    let i = BondIdentifier::Isin(Isin::new("US0378331005"));

    assert_eq!(c, BondIdentifier::Cusip(Cusip::new("037833100")));
    assert_eq!(i, BondIdentifier::Isin(Isin::new("US0378331005")));
    assert_ne!(c, i);

    match c {
        BondIdentifier::Cusip(ref id) => assert_eq!(id.as_str(), "037833100"),
        BondIdentifier::Isin(_) => panic!("expected Cusip"),
    }
}

#[test]
fn expiration_date_new_checks_calendar() {
    let cases: [(u16, u8, u8, Option<&str>); 9] = [
        (2026, 12, 18, Some("20261218")),
        (2024, 2, 29, Some("20240229")), // leap day
        (9999, 12, 31, Some("99991231")),
        (2025, 2, 29, None), // not a leap year
        (2026, 4, 31, None),
        (2026, 0, 1, None),
        (2026, 13, 1, None),
        (2026, 12, 0, None),
        (10000, 1, 1, None), // wire form is a 4-digit year
    ];
    for (year, month, day, expected) in cases {
        match (ExpirationDate::new(year, month, day), expected) {
            (Ok(date), Some(text)) => assert_eq!(date.to_string(), text),
            (Err(ValidationError::InvalidDate { value, .. }), None) => {
                assert_eq!(value, format!("{year:04}-{month:02}-{day:02}"), "{year}-{month}-{day}")
            }
            (other, _) => panic!("{year}-{month}-{day}: got {other:?}"),
        }
    }
}

#[test]
fn contract_month_new_checks_range() {
    let cases: [(u16, u8, Option<&str>); 6] = [
        (2026, 1, Some("202601")),
        (2026, 12, Some("202612")),
        (9999, 12, Some("999912")),
        (2026, 0, None),
        (2026, 13, None),
        (10000, 1, None), // wire form is a 4-digit year
    ];
    for (year, month, expected) in cases {
        match (ContractMonth::new(year, month), expected) {
            (Ok(m), Some(text)) => assert_eq!(m.to_string(), text),
            (Err(ValidationError::InvalidDate { value, .. }), None) => assert_eq!(value, format!("{year:04}-{month:02}"), "{year}-{month}"),
            (other, _) => panic!("{year}-{month}: got {other:?}"),
        }
    }
}

#[test]
fn expiration_date_from_str() {
    let cases = [
        ("20261218", Some(ExpirationDate::new(2026, 12, 18).unwrap())),
        ("20240229", Some(ExpirationDate::new(2024, 2, 29).unwrap())), // leap day
        ("20250229", None),                                            // not a leap year
        ("20261340", None),                                            // month 13
        ("20261200", None),                                            // day 0
        ("202612", None),                                              // a month, not a date
        ("2026121", None),
        ("2026-12-18", None),
        ("2026121a", None),
        ("", None),
    ];
    for (input, expected) in cases {
        match (input.parse::<ExpirationDate>(), expected) {
            (Ok(date), Some(expected)) => assert_eq!(date, expected, "{input:?}"),
            (Err(err), None) => assert_eq!(
                err,
                ValidationError::InvalidDate {
                    value: input.to_owned(),
                    expected: "YYYYMMDD"
                },
                "{input:?}"
            ),
            (other, _) => panic!("{input:?}: got {other:?}"),
        }
    }
}

