#[test]
fn expiry_from_str_is_strict() {
    assert_eq!(
        "20261218".parse::<Expiry>().unwrap(),
        Expiry::Date(ExpirationDate::new(2026, 12, 18).unwrap())
    );
    assert_eq!("202612".parse::<Expiry>().unwrap(), Expiry::Month(ContractMonth::new(2026, 12).unwrap()));
    for bad in ["", "2026", "20261340", "20261218 08:30:00 US/Central", "20430504 16:00 Europe/London"] {
        assert!(
            matches!(bad.parse::<Expiry>(), Err(ValidationError::InvalidDate { ref value, .. }) if value == bad),
            "{bad:?}"
        );
    }
}

#[test]
fn expiry_from_wire_is_lenient() {
    // Contracts reach streaming paths; an unseen shape must not end the stream.
    let cases = [
        ("", None),
        ("20261218", Some(Expiry::Date(ExpirationDate::new(2026, 12, 18).unwrap()))),
        ("202612", Some(Expiry::Month(ContractMonth::new(2026, 12).unwrap()))),
        (
            "20430504 16:00 Europe/London",
            Some(Expiry::Unknown("20430504 16:00 Europe/London".into())),
        ),
        ("20261340", Some(Expiry::Unknown("20261340".into()))),
    ];
    for (raw, expected) in cases {
        assert_eq!(Expiry::from_wire(raw), expected, "{raw:?}");
    }
}

#[test]
fn expiry_accessors_match_their_variant() {
    let date = ExpirationDate::new(2026, 12, 18).unwrap();
    let month = ContractMonth::new(2026, 12).unwrap();
    // (label, expiry, expected date(), expected month())
    let cases = [
        ("date", Expiry::Date(date), Some(date), None),
        ("month", Expiry::Month(month), None, Some(month)),
        ("unknown", Expiry::Unknown("2026Q4".into()), None, None),
    ];
    for (label, expiry, expected_date, expected_month) in cases {
        assert_eq!(expiry.date(), expected_date, "{label}");
        assert_eq!(expiry.month(), expected_month, "{label}");
    }
}

